pragma solidity ^0.8.36;

import { IERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";

/**
 * @title The interface according to the ERC-4626 standard.
 */
interface IERC4626 is IERC20Upgradeable {
  /**
   * @dev Emitted when tokens are deposited into the vault via the mint and deposit methods.
   */
  event Deposit(address indexed sender, address indexed owner, uint256 assets, uint256 shares);

  /**
   * @dev Emitted when shares are withdrawn from the vault by a depositor in the redeem or withdraw methods.
   */
  event Withdraw(
    address indexed sender,
    address indexed receiver,
    address indexed owner,
    uint256 assets,
    uint256 shares
  );

  /**
   * @dev Return the address of the underlying ERC-20 token used for the vault for accounting, depositing, withdrawing.
   */
  function asset() external view returns (address);

  /**
   * @dev Calculate the total amount of underlying assets held by the vault.
   * NOTE: This method includes assets that are marked for withdrawal.
   */
  function totalAssets() external view returns (uint256);

  /**
   * @dev Calculates the amount of shares that would be exchanged by the vault for the amount of assets provided.
   * Rounds DOWN per EIP4626.
   */
  function convertToShares(uint256 assets) external view returns (uint256);

  /**
   * @dev Calculates the amount of assets that would be exchanged by the vault for the amount of shares provided.
   * Rounds DOWN per EIP4626.
   */
  function convertToAssets(uint256 shares) external view returns (uint256);

  /**
   * @dev Calculates the maximum amount of underlying assets that can be deposited in a single deposit call by the receiver.
   */
  function maxDeposit(address receiver) external view returns (uint256);

  /**
   * @dev Allows users to simulate the effects of their deposit at the current block.
   */
  function previewDeposit(uint256 assets) external view returns (uint256);

  /**
   * @dev Deposits assets of underlying tokens into the vault and grants ownership of shares to receiver.
   * Emits a {Deposit} event.
   */
  function deposit(uint256 assets, address receiver) external returns (uint256);

  /**
   * @dev Returns the maximum amount of shares that can be minted in a single mint call by the receiver.
   */
  function maxMint(address receiver) external view returns (uint256);

  /**
   * @dev Allows users to simulate the effects of their mint at the current block.
   */
  function previewMint(uint256 shares) external view returns (uint256);

  /**
   * @dev Mints exactly shares vault shares to receiver by depositing assets of underlying tokens.
   * Emits a {Deposit} event.
   */
  function mint(uint256 shares, address receiver) external returns (uint256);

  /**
   * @dev Returns the maximum amount of underlying assets that can be withdrawn from the owner balance with a single withdraw call.
   */
  function maxWithdraw(address owner) external view returns (uint256);

  /**
   * @dev Simulate the effects of their withdrawal at the current block.
   * Per EIP4626, should round UP on the number of shares required for assets.
   */
  function previewWithdraw(uint256 assets) external view returns (uint256);

  /**
   * @dev Burns shares from owner and send exactly assets token from the vault to receiver.
   * Emits a {Withdraw} event.
   * Should round UP for EIP4626.
   */
  function withdraw(uint256 assets, address receiver, address owner) external returns (uint256);

  /**
   * @dev The maximum amount of shares that can be redeemed from the owner balance through a redeem call.
   */
  function maxRedeem(address owner) external view returns (uint256);

  /**
   * @dev Simulates the effects of their redeemption at the current block.
   * Per EIP4626, should round DOWN.
   */
  function previewRedeem(uint256 shares) external view returns (uint256);

  /**
   * @dev Redeems a specific number of shares from owner and send assets of underlying token from the vault to receiver.
   * Emits a {Withdraw} event.
   * Per EIP4626, should round DOWN.
   */
  function redeem(uint256 shares, address receiver, address owner) external returns (uint256);
}

contracts/interfaces/IPoolBase.sol.content:
//Copyright Open Trade Technology Ltd. 2023. All rights reserved.

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.36;

import "./IRequestWithdrawable.sol";

import "./IServiceConfigurationV5.sol";
import "./IPoolAccessControl.sol";
import { IERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";
enum IPoolType {
  TermPool,
  FlexRatePool,
  DynamicPool
}

interface IPoolBase is IERC20Upgradeable, IRequestWithdrawable {
  function poolType() external view returns (IPoolType);

  function liquidityAssetAddr() external view returns (address);

  /**
   * @dev The ServiceConfiguration.
   */
  function serviceConfiguration() external view returns (IServiceConfigurationV5);

  /**
   * @dev The admin for the pool.
   */
  function admin() external view returns (address);

  function borrowerManagerAddr() external view returns (address);

  function borrowerWalletAddr() external view returns (address);

  function poolAccessControl() external view returns (IPoolAccessControl);

  function isPermittedLender(address) external view returns (bool);
}

contracts/interfaces/IPoolDynamic.sol.content:
//Copyright Open Trade Technology Ltd. 2023. All rights reserved.

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.36;

import "./IERC4626.sol";
import "./IServiceConfiguration.sol";

import "./IPoolBase.sol";

import "../controllers/interfaces/IPoolControllerDynamic.sol";
import "../interfaces/IPoolAccessControl.sol";
import "../interfaces/IPoolDynamicStructures.sol";

/**
 * @title The interface for liquidity pools.
 */
interface IPoolDynamic is IPoolBase {
  event PoolCreated();
  event PoolDeposit(
    address indexed lender,
    uint256 assets,
    uint256 shares,
    IPoolDynamicDepositType depositType,
    bytes32 transferTxHash
  );
  // Off-chain reconciliation reference for an off-chain deposit (e.g. bank wireId,
  // Solana txid).
  event PoolDepositPaymentRef(address indexed lender, string paymentId);

  event RedeemRequested(address indexed lender, uint256 assets, uint256 shares, bytes32 uuid);
  event RedeemAccepted(address indexed lender, uint256 assets, uint256 shares, bytes32 uuid);
  event RedeemRepay(
    address indexed lender,
    uint256 shares,
    uint256 assets,
    uint256 fees,
    bytes32 uuid,
    uint256 expectedAssets,
    address fundsDestination
  );
  // Records the withdrawn value netted by off-chain accounting.
  event RedeemRepayRecorded(address indexed lender, bytes32 indexed uuid, uint256 withdrawnValue);
  event RedeemDestinationChanged(
    address indexed lender,
    uint256 assets,
    uint256 shares,
    bytes32 uuid,
    address fundsDestination
  );

  event AccountDebit(address indexed lender, uint256 amount, uint256 shares);
  event AccountCredit(address indexed lender, uint256 amount, uint256 shares);
  event AccountAdjustment(address indexed lender, uint256 debit, uint256 credit, IPoolDynamicAdjustmentKind kind);
  event TransferAssets(address indexed fundsDestination, uint256 amount);
  event ExchangeRateSet(
    uint256 _exchangeRate,
    int256 interestRate,
    uint256 typeDependantChangeParam,
    uint256 exchangeRateMaturityDay
  );

  function borrowerWalletAddr() external view returns (address);

  function transferToBorrowerWallet(uint256 assets) external;
  function depositOffChain(uint256 assets, address lender, string calldata paymentId) external returns (uint256 shares);
  function depositFromTransfer(
    uint256 assets,
    address lender,
    bytes32 transferTxHash
  ) external returns (uint256 shares);
  /**
   * @dev The PoolController contract
   */
  function poolControllerDynamic() external view returns (IPoolControllerDynamic);

  function accountings() external view returns (IPoolAccountingsDynamic memory);

  /**
   * @dev The current configurable pool settings.
   */
  function settings() external view returns (IPoolConfigurableSettingsDynamic calldata settings);
  function setIndicativeAndCollateralRates(int256 _indicativeInterestRate, uint256 _collateralRate) external;
  function setExchangeRate(
    uint256 _exchangeRate,
    uint256 typeDependantChangeParam,
    uint256 exchangeRateMaturityDay,
    int256 interestRate
  ) external;
  // function setExchangeRateDynamic(uint256 _exchangeRate) external;
  // function setExchangeRateLinear(uint256 _exchangeRate, uint256 exchangeRateChange, uint256 interestRate) external;
  // function setExchangeRateCompounding(
  //   uint256 _exchangeRate,
  //   uint256 exchangeRateCompoundingRate,
  //   uint256 interestRate
  // ) external;
  // function setExchangeRateAtMaturity(
  //   uint256 _exchangeRate,
  //   uint256 _exchangeRateAtMaturity,
  //   uint256 _exchangeRateMaturityDay,
  //   uint256 interestRate
  // ) external;

  function assetBalanceOf(address lender) external view returns (uint256);
  function addAdjustmentAmount(address lender, uint256 debit, uint256 credit, IPoolDynamicAdjustmentKind kind) external;

  function state() external view returns (IPoolLifeCycleStateDynamic);
  function asset() external view returns (address);
  function decimals() external view returns (uint8);
  function exchangeRate() external view returns (uint256);
  function convertToShares(uint256 assets) external view returns (uint256 shares);
  function convertToAssets(uint256 shares) external view returns (uint256 assets);
  function totalAssets() external view returns (uint256);
  function totalAvailableAssets() external view returns (uint256 assets);

  function deposit(uint256 assets, address lender) external returns (uint256 shares);
  /**
   * @dev Submits a withdrawal request, incurring a fee.
   */
  function requestRedeem(uint256 shares) external returns (uint256 assets);
  function maxRedeemRequest(address owner) external view returns (uint256 maxShares);
  function unpaidDirectTransferShares(address lender) external view returns (uint256);
  function changeRedemptionDestination(address lender, bytes32 uuid, address fundsDestination) external;
  function acceptRedemption(address lender, bytes32 uuid) external;
  function repayRedemption(address lender, uint256 repayment, uint256 fees, bytes32 uuid) external;

  function getActiveWithdraws() external view returns (IPoolWithdrawDynamic[] memory);
  function getPoolDynamicConfigurationState() external view returns (IPoolConfigurationStateDynamic memory);
  function getPoolDynamicOverviewState() external view returns (IPoolOverviewStateDynamic memory);
  function getPoolDynamicAccountState(address lender) external view returns (IPoolAccountStateDynamic memory);
}

