import { EnumerableSet } from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

import "../interfaces/IPoolDynamic.sol";
import "../interfaces/IPoolDynamicStructures.sol";

/**
 * @title Heavy execution logic for PoolDynamic.
 * @dev Linked into PoolDynamic via delegatecall, so this bytecode does not count
 * toward PoolDynamic's contract size.
 */
library PoolLibDynamic {
  using EnumerableSet for EnumerableSet.Bytes32Set;

  error InvalidAccess();
  error ExchangeRateInvalid();
  error NotLender();
  error RedemptionNotFound();
  error RedeemExceedsBalance();
  error ZeroAmount();
  error InvalidRedemptions();

  function exchangeRate(address pool) public view returns (uint256) {
    return
      _exchangeRate(
        IPoolDynamic(pool).accountings(),
        IPoolDynamic(pool).poolControllerDynamic().settings().exchangeRateType
      );
  }

  function _exchangeRate(
    IPoolAccountingsDynamic memory a,
    IPoolDynamicExchangeRateType exchangeRateType
  ) internal view returns (uint256 _rate) {
    uint256 numberOfDays = (block.timestamp / 1 days) - a.exchangeRateSetDay;
    if (exchangeRateType == IPoolDynamicExchangeRateType.Dynamic) {
      _rate = a.exchangeRate;
    } else if (exchangeRateType == IPoolDynamicExchangeRateType.Linear) {
      _rate = a.exchangeRate + numberOfDays * (a.exchangeRateChangeRate);
    } else if (exchangeRateType == IPoolDynamicExchangeRateType.Compounding) {
      if (numberOfDays > 0) {
        _rate = a.exchangeRate;
        if (numberOfDays > 7) {
          revert ExchangeRateInvalid();
        }
        for (uint256 i = 0; i < numberOfDays; i++) {
          _rate = (_rate * (a.exchangeRateCompoundingRate)) / (1e18);
        }
      } else {
        _rate = a.exchangeRate;
      }
    } else if (exchangeRateType == IPoolDynamicExchangeRateType.Term) {
      uint256 duration = a.exchangeRateMaturityDay - a.exchangeRateSetDay;

      if (numberOfDays >= duration) {
        _rate = a.exchangeRateAtMaturity;
      } else {
        if (a.exchangeRateAtMaturity > a.exchangeRate) {
          _rate = a.exchangeRate + ((numberOfDays * (a.exchangeRateAtMaturity - a.exchangeRate)) / duration);
        } else {
          _rate = a.exchangeRate - (numberOfDays * (a.exchangeRate - a.exchangeRateAtMaturity)) / duration;
        }
      }
    } else {
      revert ExchangeRateInvalid();
    }
  }

  function _convertToAssets(
    IPoolAccountingsDynamic memory a,
    IPoolDynamicExchangeRateType exchangeRateType,
    uint256 shares
  ) internal view returns (uint256) {
    return (_exchangeRate(a, exchangeRateType) * shares) / 1e18;
  }

  function _convertToShares(
    IPoolAccountingsDynamic memory a,
    IPoolDynamicExchangeRateType exchangeRateType,
    uint256 assets
  ) internal view returns (uint256) {
    return (assets * 1e18) / _exchangeRate(a, exchangeRateType);
  }

  /**
   * @dev Shared body of deposit, depositOffChain and depositFromTransfer.
   */
  function executeDeposit(
    address pool,
    IPoolAccountingsDynamic storage accountings,
    mapping(address => IPoolLenderDataDynamic) storage lenderData,
    uint256 assets,
    address lender
  ) public returns (uint256 shares) {
    if (assets == 0) revert ZeroAmount();

    IPoolDynamicExchangeRateType exchangeRateType = IPoolDynamic(pool)
      .poolControllerDynamic()
      .settings()
      .exchangeRateType;
    shares = _convertToShares(accountings, exchangeRateType, assets);
    // At a high enough exchange rate the division floors to 0; the deposit would
    // otherwise take the lender's assets and mint them nothing.
    if (shares == 0) revert ZeroAmount();

    accountings.totalAssetsDeposited += assets;
    lenderData[lender].assetsDeposited += assets;
  }

  function requestRedeemExecute(
    address pool,
    IPoolAccountingsDynamic storage accountings,
    mapping(address => IPoolLenderDataDynamic) storage lenderData,
    mapping(bytes32 => IPoolWithdrawDynamic) storage activeWithdraws,
    EnumerableSet.Bytes32Set storage activeWithdrawKeys,
    address lender,
    uint256 shares,
    bool transferRedeem
  ) public returns (uint256 assets) {
    IPoolDynamicExchangeRateType exchangeRateType = IPoolDynamic(pool)
      .poolControllerDynamic()
      .settings()
      .exchangeRateType;
    assets = _convertToAssets(accountings, exchangeRateType, shares);

    if (shares == 0) {
      revert ZeroAmount();
    }
    // At a low enough exchange rate the division floors to 0; the request would
    // otherwise burn the lender's shares at repay and record nothing withdrawn.
    if (assets == 0) {
      revert ZeroAmount();
    }
    if (shares > IPoolDynamic(pool).maxRedeemRequest(lender)) {
      revert RedeemExceedsBalance();
    }
    if (lenderData[lender].outstandingRequests > 100) {
      revert InvalidRedemptions();
    }

    lenderData[lender].requestedShares += shares;
    lenderData[lender].requestedAssets += assets;
    lenderData[lender].outstandingRequests += 1;
    if (transferRedeem) {
      lenderData[lender].unpaidDirectTransferShares += shares;
    }
    bytes32 uuid = keccak256(abi.encodePacked(block.timestamp, lender, shares, assets));

    if (activeWithdraws[uuid].lender != address(0)) {
      revert InvalidRedemptions();
    }

    activeWithdraws[uuid] = IPoolWithdrawDynamic({
      uuid: uuid,
      lender: lender,
      assets: assets,
      shares: shares,
      stage: IPoolDynamicWithdrawStage.Requested,
      fundsDestination: lender,
      transferRedeem: transferRedeem
    });
    if (!activeWithdrawKeys.add(uuid)) {
      revert InvalidAccess();
    }
    emit IPoolDynamic.RedeemRequested(lender, assets, shares, uuid);
    return assets;
  }

  /**
   * @dev Accept stage. With interestDuringWithdraw on the payout is recomputed at the
   * accept-time rate and locked; with it off the value locked at request is kept.
   */
  function acceptRedemption(
    address pool,
    mapping(bytes32 => IPoolWithdrawDynamic) storage activeWithdraws,
    IPoolAccountingsDynamic storage accountings,
    mapping(address => IPoolLenderDataDynamic) storage lenderData,
    address lender,
    bytes32 uuid
  ) public {
    IPoolWithdrawDynamic storage w = activeWithdraws[uuid];
    if (w.stage != IPoolDynamicWithdrawStage.Requested) {
      revert RedemptionNotFound();
    }
    if (w.lender != lender) {
      revert NotLender();
    }

    uint256 shares = w.shares;
    // Unwind the requested counters by the request-time value, independent of the
    // value locked below, so requestedAssets does not drift by the interest earned
    // across the window.
    uint256 requestAssets = w.assets;

    IPoolControllerDynamic controller = IPoolDynamic(pool).poolControllerDynamic();
    (bool interestDuringWithdraw, ) = controller.interestDuringWithdrawSettings();
    // With interestDuringWithdraw on, the locked value is recomputed at the accept-time
    // rate and can floor to 0 if the rate has fallen since request (negative-yield /
    // Term-down). That is the settled value, not an error.
    uint256 lockedAssets = interestDuringWithdraw
      ? _convertToAssets(accountings, controller.settings().exchangeRateType, shares)
      : requestAssets;

    w.stage = IPoolDynamicWithdrawStage.Accepted;
    w.assets = lockedAssets;

    lenderData[lender].acceptedShares += shares;
    lenderData[lender].acceptedAssets += lockedAssets;
    lenderData[lender].requestedShares -= shares;
    lenderData[lender].requestedAssets -= requestAssets;
    emit IPoolDynamic.RedeemAccepted(lender, lockedAssets, shares, uuid);
  }

  function executeRepayRedemption(
    mapping(bytes32 => IPoolWithdrawDynamic) storage activeWithdraws,
    IPoolAccountingsDynamic storage accountings,
    mapping(address => IPoolLenderDataDynamic) storage lenderData,
    EnumerableSet.Bytes32Set storage activeWithdrawKeys,
    address lender,
    bytes32 uuid
  ) public returns (uint256 shares, uint256 assets, address fundsDestination, bool isTransferRedeem) {
    IPoolWithdrawDynamic storage w = activeWithdraws[uuid];
    if (w.stage != IPoolDynamicWithdrawStage.Accepted) {
      revert RedemptionNotFound();
    }
    if (w.lender != lender) {
      revert NotLender();
    }
    shares = w.shares;
    assets = w.assets;
    fundsDestination = w.fundsDestination;
    isTransferRedeem = w.transferRedeem;

    lenderData[lender].acceptedShares -= shares;
    lenderData[lender].acceptedAssets -= assets;
    lenderData[lender].outstandingRequests -= 1;
    if (isTransferRedeem) {
      // Clamped: a redemption requested before this counter existed has nothing
      // recorded to take off, and its repay must still land.
      uint256 parked = lenderData[lender].unpaidDirectTransferShares;
      lenderData[lender].unpaidDirectTransferShares = parked > shares ? parked - shares : 0;
    }

    // Record the full locked value of the burned redemption, not the cash repayment:
    // the whole redemption is burned even when the cash paid is partial.
    lenderData[lender].assetsWithdrawn += assets;
    accountings.totalAssetsWithdrawn += assets;

    delete activeWithdraws[uuid];
    if (!activeWithdrawKeys.remove(uuid)) {
      revert InvalidAccess();
    }

    // Emit the recorded value so off-chain accounting nets the exact amount.
    emit IPoolDynamic.RedeemRepayRecorded(lender, uuid, assets);
  }
}

