//Copyright Open Trade Technology Ltd. 2023. All rights reserved.

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.36;
// A calldata parameter of PoolFactoryDynamic.createPool, so its shape is part of that
// selector, and the factory is its own beacon: the factory's own code can never be
// replaced. A member added here leaves the deployed factory encoding a selector the
// upgraded pool no longer has, and every create reverts. Settings that are not needed
// at creation belong in PoolControllerDynamic as appended storage.
struct IPoolConfigurableSettingsDynamic {
  address borrowerManager;
  address borrowerWalletAddr;
  address feeCollectorAddress;
  // Dead on-chain: nothing reads these, they are only surfaced in the state getters.
  // transferOutDays drifts from the off-chain copy, which is the value shown to users.
  uint256 closeOfDepositTime;
  uint256 closeOfWithdrawTime;
  uint256 transferOutDays;
  IPoolDynamicExchangeRateType exchangeRateType;
}

struct PoolAddressListDynamic {
  address liquidityAsset;
  address poolAdmin;
  address serviceConfiguration;
  address poolControllerFactoryDynamic;
  address poolAccessControlFactory;
}
struct IPoolAccountingsDynamic {
  uint256 totalAssetsDeposited;
  uint256 totalAssetsWithdrawn;
  uint256 exchangeRate;
  uint256 exchangeRateSetDay;
  uint256 exchangeRateChangeRate;
  uint256 exchangeRateCompoundingRate;
  uint256 exchangeRateAtMaturity;
  uint256 exchangeRateMaturityDay;
  int256 interestRate;
  int256 indicativeInterestRate;
  uint256 collateralRate;
}
enum IPoolDynamicExchangeRateType {
  Undefined,
  Dynamic,
  Linear,
  Compounding,
  Term
}
enum IPoolLifeCycleStateDynamic {
  Initialized,
  Active,
  Closed,
  DisruptionOrDefault
}
enum IPoolDepositActiveStateDynamic {
  Active,
  Inactive
}
enum IPoolWithdrawActiveStateDynamic {
  Active,
  Inactive
}
enum IPoolDynamicWithdrawStage {
  UndefinedStage,
  Requested,
  Accepted,
  Repaid
}
// ContractDeposit: lender approves and calls deposit() directly.
// OffChainDeposit: client transfers to a company deposit address, ops record it on chain.
// TransferDeposit: client transfers straight to the pool, admin accepts it.
// CrossChainDeposit: defined but unused.
// LYT pools use the same names without CrossChainDeposit, so their numbering differs.
enum IPoolDynamicDepositType {
  UndefinedDeposit,
  ContractDeposit,
  OffChainDeposit,
  CrossChainDeposit,
  TransferDeposit
}
// How addAdjustmentAmount moves the accounting totals alongside the share burn/mint.
// BalanceOnly moves no totals (e.g. fee collection). DepositCorrection: debit reduces
// deposited, credit increases it. Withdrawal: debit increases withdrawn, credit
// reduces it.
enum IPoolDynamicAdjustmentKind {
  BalanceOnly,
  DepositCorrection,
  Withdrawal
}
struct IPoolLenderDataDynamic {
  uint256 requestedShares;
  uint256 requestedAssets;
  uint256 acceptedShares;
  uint256 acceptedAssets;
  uint256 assetsDeposited;
  uint256 assetsWithdrawn;
  uint256 outstandingRequests;
  // Shares this lender sent to the pool address to open a redemption, still held
  // there. They have left balanceOf(lender) and are counted in requestedShares or
  // acceptedShares, so free shares add them back. At or below the amount the pool
  // address actually holds for the lender, so free shares can only understate: a
  // redemption opened before this counter existed has nothing recorded against it.
  uint256 unpaidDirectTransferShares;
}

struct IPoolWithdrawDynamic {
  bytes32 uuid;
  address lender;
  uint256 assets;
  uint256 shares;
  IPoolDynamicWithdrawStage stage;
  address fundsDestination;
  bool transferRedeem;
}
struct IPoolConfigurationStateDynamic {
  address poolAddr;
  string name;
  string symbol;
  address poolAccessControl;
  address poolControllerDynamic;
  uint256 activatedAt;
  // PoolControllerDynamic
  address serviceConfiguration;
  address liquidityAssetAddr;
  address poolAdmin;
  address borrowerManager;
  address borrowerWalletAddr;
  address feeCollectorAddress;
  uint256 closeOfDepositTime;
  uint256 closeOfWithdrawTime;
  uint256 transferOutDays;
  IPoolDynamicExchangeRateType exchangeRateType;
  bool interestDuringWithdraw;
  uint64 interestDuringWithdrawDays;
}
struct IPoolOverviewStateDynamic {
  address poolAddr;
  uint256 state;
  // accountings
  uint256 totalAssetsDeposited;
  uint256 totalAssetsWithdrawn;
  uint256 totalAssets;
  uint256 totalShares;
  uint256 exchangeRate;
  uint256 exchangeRateAtSetDay;
  uint256 exchangeRateSetDay;
  uint256 exchangeRateChangeRate;
  uint256 exchangeRateCompoundingRate;
  uint256 exchangeRateAtMaturity;
  uint256 exchangeRateMaturityDay;
  int256 interestRate;
  int256 indicativeInterestRate;
  uint256 collateralRate;
  //
  IPoolWithdrawDynamic[] activeWithdraws;
}

struct IPoolAccountStateDynamic {
  address poolAddr;
  address accountAddr;
  address liquidityAssetAddr;
  uint256 tokenBalance;
  uint256 assetBalance;
  uint256 maxWithdrawRequest;
  uint256 maxRedeemRequest;
  // lenderData

  uint256 requestedSharesOf;
  uint256 requestedAssetsOf;
  uint256 acceptedShares;
  uint256 acceptedAssets;
  uint256 assetsDeposited;
  uint256 assetsWithdrawn;
}

